import { useState } from "react";
export default function EmailForm() {
  const [email, setEmail] = useState("");
  return <form onSubmit={e => { e.preventDefault(); console.log(email); }}>
    <label>Email <input type="email" value={email} onChange={e => setEmail(e.target.value)} required /></label>
    <button type="submit">Save</button>
  </form>;
}

import { useState } from "react";
export default function LevelPicker() {
  const [level, setLevel] = useState("beginner");
  return <label>Level <select value={level} onChange={e => setLevel(e.target.value)}><option value="beginner">Beginner</option><option value="advanced">Advanced</option></select></label>;
}

function RequiredName() {
